<script setup>
import { computed, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
import { activePersona, createIncident, notify, state } from '../stores/demo'
const route=useRoute();const me=activePersona;const showForm=ref(Boolean(route.query.new));const selected=ref(state.incidents[0]?.id || '');const form=reactive({loanId:String(route.query.loan || ''),category:'Condición de herramienta',detail:''})
const loans=computed(()=>state.loans.filter(l=>me.value.id==='admin'||l.borrowerId===me.value.id||l.ownerId===me.value.id))
const incidents=computed(()=>state.incidents.filter(i=>me.value.id==='admin'||i.reporterId===me.value.id||loans.value.some(l=>l.id===i.loanId)))
const current=computed(()=>incidents.value.find(i=>i.id===selected.value))
function submit(){const loan=state.loans.find(l=>l.id===form.loanId);if(!loan||!form.detail.trim())return;createIncident({loan,category:form.category,detail:form.detail.trim()});selected.value=state.incidents[0].id;form.detail='';showForm.value=false;notify('Reporte enviado. El equipo podrá revisarlo.')}
function updateStatus(incident,status){incident.status=status;notify('Estado del incidente actualizado.')}
function statusLabel(status){return ({received:'Recibido',reviewing:'En revisión',resolved:'Resuelto'})[status]||status}
</script>
<template>
  <div class="page-container incidents-page"><div class="page-title-row"><div class="page-title-block"><span class="eyebrow">CU-08 · RESPONSABILIDAD Y TRAZABILIDAD</span><h1>Resolverlo juntos.</h1><p>Un reporte claro ayuda a entender qué pasó y cuidar a las personas.</p></div><button v-if="me.id!=='admin'" class="button button-primary" @click="showForm=!showForm">＋ Reportar incidente</button></div>
    <section v-if="showForm && me.id!=='admin'" class="incident-form-card"><div class="form-card-heading"><div><span class="eyebrow">NUEVO REPORTE</span><h2>¿Qué ocurrió?</h2></div><button class="icon-close" @click="showForm=false">×</button></div><form @submit.prevent="submit"><label class="field"><span>Préstamo asociado</span><select v-model="form.loanId" required><option value="" disabled>Selecciona un préstamo</option><option v-for="loan in loans" :key="loan.id" :value="loan.id">{{ loan.id }} · {{ loan.toolTitle }}</option></select></label><label class="field"><span>Tipo de incidente</span><select v-model="form.category"><option>Condición de herramienta</option><option>Devolución atrasada</option><option>Daño durante el uso</option><option>Problema de coordinación</option><option>Otro</option></select></label><label class="field"><span>Descripción</span><textarea v-model.trim="form.detail" rows="4" maxlength="500" placeholder="Describe los hechos y cuándo ocurrieron. Evita incluir información personal innecesaria." required></textarea></label><div class="request-terms"><span>◇</span><p>El reporte quedará asociado a la transacción para que el equipo pueda revisar sus antecedentes.</p></div><button class="button button-primary" :disabled="!form.loanId||!form.detail.trim()">Enviar reporte <span>↗</span></button></form></section>
    <div v-if="incidents.length" class="incident-layout"><aside class="incident-list"><div class="incident-list-header"><strong>Reportes</strong><span>{{ incidents.length }}</span></div><button v-for="incident in incidents" :key="incident.id" class="incident-list-item" :class="{selected:selected===incident.id}" @click="selected=incident.id"><span class="incident-list-icon">◉</span><span><strong>{{ incident.category }}</strong><small>{{ incident.id }} · {{ incident.created }}</small></span><i :class="`incident-dot dot-${incident.status}`"></i></button></aside>
      <article v-if="current" class="incident-detail-card"><div class="incident-detail-heading"><div><span class="eyebrow">{{ current.id }} · {{ current.loanId }}</span><h2>{{ current.category }}</h2></div><span class="status-pill" :class="`status-${current.status}`"><i></i>{{ statusLabel(current.status) }}</span></div><div class="incident-info-grid"><div><span>HERRAMIENTA</span><strong>{{ current.toolTitle }}</strong></div><div><span>REPORTADO POR</span><strong>{{ current.reporter }}</strong></div><div><span>FECHA</span><strong>{{ current.created }}</strong></div></div><div class="incident-description"><span>DESCRIPCIÓN DEL REPORTE</span><p>{{ current.detail }}</p></div>
        <div v-if="me.id==='admin'" class="admin-actions"><span class="eyebrow">ACCIONES DE OPERACIÓN</span><div><button v-if="current.status==='received'" class="button button-secondary" @click="updateStatus(current,'reviewing')">Marcar en revisión</button><button v-if="current.status!=='resolved'" class="button button-primary" @click="updateStatus(current,'resolved')">Marcar resuelto <span>✓</span></button><span v-if="current.status==='resolved'" class="resolved-note">✓ Incidente resuelto</span></div></div><div v-else class="incident-next-step"><span>✳</span><p>El equipo revisará el reporte y la información del préstamo. Mantén la coordinación con la otra persona por los canales acordados.</p></div>
      </article></div>
    <div v-else-if="!showForm" class="empty-panel"><div class="empty-icon">◉</div><h3>No tienes reportes asociados</h3><p>Si surge un problema durante un préstamo, puedes dejar constancia aquí.</p><button class="button button-secondary" @click="showForm=true">Reportar un incidente</button></div>
  </div>
</template>
